package com.example.proyectolp.service;
import com.example.proyectolp.model.*;import com.example.proyectolp.repository.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
public class GamificationService {private final SupabaseService db;private final Clock clock;private final CreditService credits;private final XpService xp;private final BadgeService badges;private final MissionService missions;public GamificationService(SupabaseService db,Clock clock){this.db=db;this.clock=clock;credits=new CreditService(db);xp=new XpService(db);badges=new BadgeService(db);missions=new MissionService(db,clock);}private LocalDate today(){return LocalDate.now(clock.withZone(ZoneId.of("America/Bogota")));}
 public RewardResult habitCompleted(long id,LocalDate date,boolean done)throws Exception{int c=credits.habit(id,date,done,today())?1:0;boolean todayDone=date.equals(today())&&done;int x=todayDone&&xp.grant(10,"Hábito completado","xp:habit:"+id+":"+date)?10:0;if(x>0)x+=missions.event("HABITS_2",xp);return result(c,x,c>0?new String[]{"PRIMER_HABITO"}:new String[0],"completar el hábito");}
 public RewardResult taskCompleted(long id,boolean hasProject)throws Exception{int c=credits.task(id,hasProject)?(hasProject?1:3):0;int x=xp.grant(20,"Tarea completada","xp:task:"+id)?20:0;if(x>0)x+=missions.event("TASKS_2",xp);return result(c,x,c>0?new String[]{"PRIMERA_TAREA"}:new String[0],"completar la tarea");}
 public RewardResult stageCompleted(long id)throws Exception{int c=credits.stage(id)?1:0;int x=xp.grant(30,"Etapa completada","xp:stage:"+id)?30:0;if(x>0)x+=missions.event("STAGE_1",xp);return result(c,x,new String[0],"completar la etapa");}
 public RewardResult projectCompleted(long id)throws Exception{int x=xp.grant(100,"Proyecto finalizado","xp:project:"+id)?100:0;return result(0,x,new String[]{"PRIMER_PROYECTO"},"finalizar el proyecto");}
 public RewardResult goalContribution(long id,BigDecimal target,BigDecimal oldAmount,BigDecimal newAmount)throws Exception{int c=credits.goalContribution(id,target,oldAmount,newAmount);int milestones=CreditRules.crossedSavingsMilestones(target,oldAmount,newAmount);int x=0;for(int i=1;i<=milestones;i++)if(xp.grant(25,"Hito de meta","xp:goal:"+id+":m"+CreditRules.goalMilestoneNumber(target,oldAmount,newAmount,i)))x+=25;if(newAmount.compareTo(target)>=0&&oldAmount.compareTo(target)<0&&xp.grant(100,"Meta completada","xp:goal-complete:"+id))x+=100;return result(c,x,newAmount.compareTo(target)>=0?new String[]{"PRIMERA_META"}:new String[0],"aportar a la meta");}
 public RewardResult workoutFinished(long sessionId)throws Exception{int x=xp.grant(30,"Sesión de entrenamiento","xp:workout:"+sessionId)?30:0;if(x>0)x+=missions.event("WORKOUT_1",xp);return result(0,x,new String[0],"finalizar el entrenamiento");}
 public RewardResult financialMovement(long id)throws Exception{int x=missions.event("FINANCE_1",xp);return result(0,x,new String[0],"registrar movimiento");}
 private RewardResult result(int c,int x,String[] requested,String reason)throws Exception{List<String> gained=new ArrayList<>(badges.unlock(requested));int total=xp.total(),level=LevelCurve.level(total);if(level>=5)gained.addAll(badges.unlock("NIVEL_5"));UserStats st=new UserStatsRepository(db).get();if(st.current_streak>=7)gained.addAll(badges.unlock("RACHA_7"));if(st.current_streak>=30)gained.addAll(badges.unlock("RACHA_30"));int earned=new CreditLedgerRepository(db).list().stream().filter(e->e.credits>0).mapToInt(e->e.credits).sum();if(earned>=50)gained.addAll(badges.unlock("CREDITOS_50"));String msg=c>0?"+"+c+" créditos ($"+String.format(java.util.Locale.forLanguageTag("es-CO"),"%,d",c*CreditRules.COP_PER_CREDIT)+" COP) por "+reason:x>0?"+"+x+" XP por "+reason:"";if(!gained.isEmpty())msg+=(msg.isEmpty()?"":" · ")+"Insignias: "+String.join(", ",gained);if(!msg.isEmpty())NotificationService.getInstance().show(msg);return new RewardResult(c,x,gained,msg);}
 public List<DailyMission> dailyMissions()throws Exception{return missions.today();}public int xpTotal()throws Exception{return xp.total();}public Set<String> unlockedBadges()throws Exception{return badges.unlocked();}
 public void refreshStreakBadges()throws Exception{int streak=new UserStatsRepository(db).get().current_streak;if(streak>=7)badges.unlock("RACHA_7");if(streak>=30)badges.unlock("RACHA_30");}
}
